    57   * Common TLV function for accessing TLVs in a data stream.
    58   */
    59  int fuzz_get_tlv_comn(FUZZ_DATA *fuzz,
    60                        TLV *tlv)
    61  {
    62    int rc = 0;
    63    size_t data_offset;
    64    TLV_RAW *raw;
    65
    66    /* Start by casting the data stream to a TLV. */
    67    raw = (TLV_RAW *)&fuzz->state.data[fuzz->state.data_pos];
    68    data_offset = fuzz->state.data_pos + sizeof(TLV_RAW);
    69
    70    /* Set the TLV values. */
    71    tlv->type = to_u16(raw->raw_type);
    72    tlv->length = to_u32(raw->raw_length);
    73    tlv->value = &fuzz->state.data[data_offset];
    74
    75    FV_PRINTF(fuzz, "TLV: type %x length %u\n", tlv->type, tlv->length);
    76
    77    /* Use uint64s to verify lengths of TLVs so that overflow problems don't
    78       matter. */
    79    uint64_t check_length = data_offset;
    80    check_length += tlv->length;
    81
    82    uint64_t remaining_len = fuzz->state.data_len;
    83    FV_PRINTF(fuzz, "Check length of data: %lu \n", check_length);
    84    FV_PRINTF(fuzz, "Remaining length of data: %lu \n", remaining_len);
    85
    86    /* Sanity check that the TLV length is ok. */
    87    if(check_length > remaining_len) {
    88      FV_PRINTF(fuzz, "Returning TLV_RC_SIZE_ERROR\n");
    89      rc = TLV_RC_SIZE_ERROR;
    90    }
    91
    92    return rc;
    93  }
