    85    int rc;
    86    timediff_t interval_ms;
    87    timediff_t timeout_ms = Curl_pp_state_timeout(pp, disconnecting);
    88    struct Curl_easy *data = conn->data;
    89    CURLcode result = CURLE_OK;
